    @Test
    public void testCountAssimilated01() {
        int[][] input = new int[][]{
                {10, 10, 10},
                {10, 10, 10},
                {10, 10, 10}
        };
        int result = Matrix.countAssimilated(input);

        assertEquals(9, result);
    }

    @Test
    public void testCountAssimilated02() {
        int[][] input = new int[][]{
                {5, 10, 3},
                {6, 9, 6},
                {3, 3, 15}
        };
        int result = Matrix.countAssimilated(input);

        assertEquals(4, result);
    }

